<?php
declare(strict_types=1);
$rounds=[];
foreach([1=>'v3-options',2=>'v3-round2',3=>'v3-round3',4=>'v3-round4'] as $n=>$folder){
 $m=json_decode(file_get_contents(__DIR__.'/audio/effects/'.$folder.'/generation-manifest.json'),true,64,JSON_THROW_ON_ERROR);
 $rounds[$n]=['folder'=>$folder,'groups'=>array_column($m['groups'],null,'id'),'sounds'=>$m['sounds']];
}
$approved=json_decode(file_get_contents(__DIR__.'/audio/effects/approved.json'),true,64,JSON_THROW_ON_ERROR);
$groups=array_values($rounds[1]['groups']);usort($groups,fn($a,$b)=>(int)isset($approved[$a['id']])<=>(int)isset($approved[$b['id']]));
function optionEscape(string $s): string{return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
$ready=0;foreach($rounds[4]['sounds'] as $sound)if(is_file(__DIR__.'/audio/effects/v3-round4/'.$sound['file']))++$ready;
$notes=[
 'commit'=>'A simple electronic confirm. Four new half-second takes using the prompt “Electronic confirm sound”.',
 'burn-bonus'=>'Selected Round 3 take 2, raised by 6 dB. Prompt: roaring fire quickly consumes paper.',
 'confirm-mark'=>'Pending damage: a warning that a later connecting attack can trigger extra damage. This is the status being applied, before the damage payoff.',
 'confirm-cash'=>'Confirmed damage: the later hit triggers that extra damage. Your choice is take 1 from the Round 2 Mark damage set, reassigned here.',
 'hit-light'=>'Take 2 has its empty tail removed and is raised by 6 dB.',
 'round-ready'=>'Take 1 is raised by 6 dB, with excess quiet trimmed.',
 'block'=>'The previously selected take 3 remains raised by 6 dB.'
];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><base href="../"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SFX v3 Auditions · El’s Invitation</title><link rel="stylesheet" href="adventure/world.css?v=<?=filemtime(__DIR__.'/world.css')?>"><style>
main{max-width:1400px;padding-bottom:60px}.intro{max-width:800px;line-height:1.8;color:var(--muted)}.approved{display:flex;align-items:center;flex-wrap:wrap;gap:20px;padding:20px;background:#e8eddc;border:1px solid #a2b78d;border-radius:10px;margin:25px 0}.approved strong{font-family:Literata,Georgia,serif}.approved small{display:block;color:var(--muted);margin-top:6px}.approved audio{width:300px;max-width:100%}.effect-index{display:flex;flex-wrap:wrap;gap:7px;margin:25px 0}.effect-index a{padding:7px 10px;border:1px solid var(--line);background:#fff9ed;border-radius:6px;font-size:11px;text-decoration:none}.effect-group{border:1px solid var(--line);background:#fff8e9;border-radius:10px;margin-bottom:14px;scroll-margin-top:15px}.effect-group summary{padding:20px;cursor:pointer;list-style:none;display:flex;align-items:center;justify-content:space-between;gap:12px}.effect-group summary::-webkit-details-marker{display:none}.effect-group summary strong{font-family:Literata,Georgia,serif;font-size:21px;font-weight:500}.effect-group summary span{font-size:11px;color:var(--muted)}.effect-group summary span:after{content:' +';font-size:18px}.effect-group[open] summary span:after{content:' −'}.effect-prompt{margin:0 20px 18px;color:var(--muted);font-size:12px;line-height:1.7}.take-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:0 20px 20px}.take{padding:14px 10px;background:#f2e9d8;border:1px solid #decdb0;border-radius:8px}.take strong{display:block;font-size:12px;margin:0 5px 10px}.take button{display:block;width:100%;background:#fff9ed}.take button[aria-pressed=true]{background:#3d654b;color:#fff8e9}.audition-status{font-size:12px;line-height:1.6;color:var(--muted);min-height:20px}.pending{font-size:12px;color:var(--muted);padding:15px}.status{font-size:12px;color:var(--muted)}@media(max-width:1100px){.take-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.world-header{flex-direction:column;align-items:start}.take-grid{grid-template-columns:1fr}.effect-group summary{padding:16px}.effect-group summary strong{font-size:18px}.approved{padding:16px}}
.selected-badge{display:inline-block;margin-left:10px;padding:5px 8px;background:#e2ebd6;border-radius:5px;font:11px 'DM Sans',sans-serif;color:#3d654b}.take.selected{border:2px solid #638258;background:#e9efdf}.usage-note{margin:0 20px 16px;color:#594733;font-size:12px;line-height:1.8;max-width:850px}.previous-options{margin:0 20px 20px;border-top:1px solid var(--line)}.previous-options>summary{font-size:12px;color:var(--muted);padding:13px 0}.previous-options .take-grid{padding:0}.duration{font-size:10px;line-height:1.6;color:var(--muted);margin:8px 4px 0}</style></head><body><header class="world-header"><a class="brand" href="adventure/"><span class="brand-sun">☀</span><span><small>EL’S INVITATION</small><strong>SFX v3 Auditions</strong></span></a><a href="adventure/soundtrack.php#effects">Sound library →</a></header><main>
<span class="eyebrow">ALL 23 EFFECTS SELECTED</span><h1>Your selected sound effects</h1>
<p class="intro">Commit move take 1 from Round 4 is applied. All 23 gameplay effects now have a selected sound, including the volume boosts and trims you reviewed. Your selections and earlier comparisons remain available below.</p>
<div class="approved"><div><strong><?=count($approved)?> selected effects are live</strong><small>Card play remains the approved 0.44-second take 1.</small></div><button data-audition="adventure/audio/effects/<?=optionEscape($approved['card-swipe']['file'])?>" data-label="Selected card play take 1" aria-pressed="false">▶ Play selected take</button></div>
<p class="status">Selection complete. Every effect below shows its applied take; previous options remain available for comparison.</p>
<p id="auditionStatus" class="audition-status" role="status">Press Play on any take to listen. Only one sample plays at a time.</p>
<nav class="effect-index" aria-label="Effect groups"><?php foreach($groups as $g): ?><a href="adventure/sound-options.php#<?=optionEscape($g['id'])?>"><?=optionEscape($g['title'])?><?=isset($approved[$g['id']])?' ✓':''?></a><?php endforeach; ?></nav>
<?php foreach($groups as $i=>$original):
$id=$original['id'];$choice=$approved[$id]??null;$available=array_filter(array_keys($rounds),fn($n)=>isset($rounds[$n]['groups'][$id]));$round=max($available);
$group=$rounds[$round]['groups'][$id];$crossSource=$choice&&isset($choice['sourceEffect']);
?>
<details class="effect-group" id="<?=optionEscape($id)?>" <?=$i===0?'open':''?>><summary><strong><?=optionEscape($group['title'])?><?php if($choice): ?><small class="selected-badge">Selected: <?=$crossSource?'Mark damage · ':''?>R<?=$choice['round']??1?> take <?=$choice['take']?></small><?php endif; ?></strong><span><?=$choice?'Applied':'Round 4 · 4 new options'?></span></summary>
<?php if(isset($notes[$id])): ?><p class="usage-note"><?=optionEscape($notes[$id])?></p><?php endif; ?>
<?php if($choice): ?><p class="usage-note">Live: <?=$crossSource?'Mark damage · ':''?>Round <?=$choice['round']??1?>, take <?=$choice['take']?> · <?=number_format($choice['durationSeconds'],2)?> seconds<?=!empty($choice['gainDb'])?' · +'.$choice['gainDb'].' dB':''?>.</p><?php endif; ?>
<?php if($crossSource): ?><div class="take-grid"><article class="take selected"><strong>Selected live edit · Mark damage R2 take 1</strong><button data-audition="adventure/audio/effects/<?=optionEscape($choice['file'])?>" data-label="Selected confirmed damage" aria-pressed="false">▶ Play</button><p class="duration"><?=number_format($choice['durationSeconds'],2)?> seconds</p></article></div><details class="previous-options"><summary>Unselected confirm-damage candidates · Round <?=$round?></summary><?php endif; ?>
<p class="effect-prompt">Prompt: “<?=optionEscape($group['prompt'])?>”</p><div class="take-grid">
<?php foreach($group['takes'] as $take): $isSelected=$choice&&!$crossSource&&($choice['round']??1)===$round&&$choice['take']===$take['take'];$file=$isSelected?$choice['file']:$rounds[$round]['folder'].'/'.$take['file']; ?>
<article class="take <?=$isSelected?'selected':''?>"><strong>Take <?=$take['take']?><?=$isSelected?' · selected':''?></strong><button data-audition="adventure/audio/effects/<?=optionEscape($file)?>" data-label="<?=optionEscape($group['title'])?> round <?=$round?> take <?=$take['take']?>" aria-label="Play <?=optionEscape($group['title'])?> take <?=$take['take']?>" aria-pressed="false">▶ Play</button><p class="duration"><?=$isSelected?number_format($choice['durationSeconds'],2):($group['duration']??1.5)?> seconds<?=$isSelected&&!empty($choice['gainDb'])?' · +'.$choice['gainDb'].' dB':''?></p></article>
<?php endforeach; ?></div><?php if($crossSource): ?></details><?php endif; ?>
<?php for($previous=$round-1;$previous>=1;--$previous): if(!isset($rounds[$previous]['groups'][$id]))continue;$old=$rounds[$previous]['groups'][$id]; ?>
<details class="previous-options"><summary>Previous options · Round <?=$previous?></summary><p class="effect-prompt">Prompt: “<?=optionEscape($old['prompt'])?>”</p><div class="take-grid"><?php foreach($old['takes'] as $take): ?><article class="take"><strong>Previous take <?=$take['take']?></strong><button data-audition="adventure/audio/effects/<?=optionEscape($rounds[$previous]['folder'].'/'.$take['file'])?>" data-label="Previous <?=optionEscape($group['title'])?> round <?=$previous?> take <?=$take['take']?>" aria-pressed="false">▶ Play</button></article><?php endforeach; ?></div></details>
<?php endfor; ?></details><?php endforeach; ?>
</main><audio id="auditionPlayer" preload="none"></audio><script>
const player=document.getElementById('auditionPlayer'),statusLine=document.getElementById('auditionStatus');let active=null,serial=0;
function reset(){if(active){active.setAttribute('aria-pressed','false');active.textContent=active.closest('.approved')?'▶ Play selected take':'▶ Play';}active=null;}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-audition]');if(!button)return;const same=active===button;serial++;const request=serial;player.pause();reset();if(same){statusLine.textContent='Stopped.';return;}active=button;button.setAttribute('aria-pressed','true');button.textContent='■ Stop';player.src=button.dataset.audition;statusLine.textContent='Playing '+button.dataset.label;try{await player.play();}catch{if(request===serial){reset();statusLine.textContent='Playback is unavailable in this browser. Try another browser to audition the samples.';}}});
player.addEventListener('ended',()=>{reset();statusLine.textContent='Ready for another take.';});
document.addEventListener('visibilitychange',()=>{if(document.hidden){serial++;player.pause();reset();}});
function openGroup(){const id=location.hash.slice(1),group=document.getElementById(id);if(group?.classList.contains('effect-group'))group.open=true;}addEventListener('hashchange',openGroup);openGroup();
</script></body></html>
